"""Generate the frozen v1/v2 datasets; fixed expected values are independently listed."""
from __future__ import annotations

import csv
import hashlib
import json
from pathlib import Path

from oracle import ORDER_COLUMNS, REFUND_COLUMNS, expected_summary

BASE = Path(__file__).resolve().parent / "fixtures"
ORDERS = [
    ("o001", "north", "CNY", "10000", "paid"),
    ("o002", "north", "CNY", "20000", "paid"),
    ("o003", "south", "CNY", "5000", "paid"),
    ("o004", "east", "CNY", "0", "paid"),
    ("o005", "east", "CNY", "9900", "cancelled"),
    ("o006", "south", "USD", "12345", "paid"),
    ("o007", "north", "USD", "2000", "paid"),
    ("o008", "east", "USD", "5000", "paid"),
    ("o009", "east", "USD", "0", "paid"),
    ("o010", "north", "CNY", "3000", "cancelled"),
    ("o011", "south", "CNY", "7000", "paid"),
    ("o012", "east", "CNY", "8000", "paid"),
    ("o013", "north", "USD", "9000", "paid"),
    ("o014", "south", "USD", "4444", "cancelled"),
]
REFUNDS = [
    ("r001", "o002", "CNY", "2500"), ("r002", "o002", "CNY", "1500"),
    ("r003", "o003", "CNY", "5000"), ("r004", "o006", "USD", "2000"),
    ("r005", "o006", "USD", "345"), ("r006", "o007", "USD", "500"),
    ("r007", "o008", "USD", "5000"), ("r008", "o011", "CNY", "3000"),
]


def write_csv(path: Path, fields: tuple, rows: list) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, lineterminator="\n")
        writer.writerow(fields)
        writer.writerows(rows)


def fixed_expected(version: int) -> dict:
    # These arithmetic answers are deliberately not generated by the SQLite oracle.
    table = [
        ("east", "CNY", 2, 8000, 0),
        ("north", "CNY", 2, 30000 if version == 1 else 32000, 4000 if version == 1 else 5000),
        ("south", "CNY", 2, 12000, 8000),
        ("east", "USD", 2, 5000, 5000),
        ("north", "USD", 2, 11000, 500),
        ("south", "USD", 1, 12345, 2345),
    ]
    return {"schema_version": 1, "cancelled_orders": 3, "totals": [
        {"region": region, "currency": currency, "paid_orders": paid,
         "gross_cents": gross, "refund_cents": refund, "net_cents": gross - refund}
        for region, currency, paid, gross, refund in table
    ]}


def main() -> None:
    for version in (1, 2):
        target = BASE / f"v{version}"
        target.mkdir(parents=True, exist_ok=True)
        orders = list(ORDERS)
        refunds = list(REFUNDS)
        if version == 2:
            orders[0] = ("o001", "north", "CNY", "12000", "paid")
            refunds.append(("r009", "o001", "CNY", "1000"))
        write_csv(target / "orders.csv", ORDER_COLUMNS, orders)
        write_csv(target / "refunds.csv", REFUND_COLUMNS, refunds)
        expected = fixed_expected(version)
        assert expected_summary(target / "orders.csv", target / "refunds.csv") == expected
        (target / "expected.json").write_text(json.dumps(expected, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    hashes = {path.relative_to(BASE).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
              for path in sorted(BASE.glob("v*/*")) if path.is_file()}
    manifest = {"schema_version": 1, "fixture_version": "F1", "files_sha256": hashes,
                "v2_change": "o001.amount_cents 10000->12000; add r009/o001/CNY/1000",
                "scope": "Frozen functional inputs and manually listed expected JSON; not collaboration evidence"}
    (BASE / "freeze_manifest.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print("FIXTURES_BUILT")


if __name__ == "__main__":
    main()
